P=Path('output/public-tag-tail-audit')
m=json.loads((P/'metrics.json').read_text());groups=json.loads((P/'natural_variants.json').read_text())
seo=[g for g in groups if g['scored_variants']>=2 and all(v['tail_type']=='explicit_seo' for v in g['variants'])]
lines=['# C_syntax: хвосты публичных объявлений','',
'Исследование исходной C_syntax без hard negatives. Порог 0.5. Данные, веса, разметка и архитектура не изменялись. Все номера строк ниже с нуля.','',
'## Метод и ограничения','',
'Сопоставлены исходные объявления с одинаковой основной частью после нормализации регистра и пробелов, но разными окончаниями. Окончания выделялись по явным SEO-заголовкам, заголовкам характеристик и, отдельно, последнему абзацу с плотным перечислением через запятую. Последний тип — кандидат, а не доказанный SEO-текст. Тексты для инференса не обрезались.','',
'Для public validation и official_208 использованы сохранённые предсказания исходной C_syntax. Для public calibration сохранённые полные признаки переданы тем же весам CatBoost; p_sgd в этом кэше вычислены полными SGD-головами, а не OOF-головами обучения. Предсказания для public train не достраивались. Source=101 согласно существующему публичному протоколу; поле отсутствует в исходном parquet.','',
'Это наблюдение естественных вариантов. Оно не изолирует эффект каждого добавленного слова и не заменяет контролируемое сравнение «один текст ± SEO». Разные варианты одного шаблона встречаются в обучении; эти результаты не являются независимой оценкой обобщения.','',
'## Что найдено','',
'| Набор | Строк | Явный SEO-хвост | Характеристики | Последний список — кандидат |','|---|---:|---:|---:|---:|']
for k,s in m['stats'].items():
 d=s['detected_rows'];lines.append(f"| {k} | {s['rows']} | {d.get('explicit_seo',0)} | {d.get('attributes',0)} | {d.get('unmarked_list_candidate',0)} |")
lines+=['',f"В сыром train из 4855 уникальных описаний {m['stats']['public_raw_10000']['unique_descriptions_by_type']['explicit_seo']} имеют обнаруженный явный SEO-заголовок. Детектор консервативный и не гарантирует полноту.",'',
f"Найдено {m['body_groups_with_distinct_tails']} групп с одинаковой основной частью и разными хвостами; в {m['groups_with_gold_changes']} группах различается gold. Для {m['groups_with_at_least_two_scored_variants']} групп доступны предсказания минимум двух вариантов; в {m['groups_with_prediction_changes']} меняется ответ C_syntax. Оба изменения связаны с блоком характеристик, а не с явно размеченным SEO-хвостом.",'',
f"Для {len(seo)} групп с явным SEO-хвостом и минимум двумя оценёнными вариантами ответ не меняется. Это преимущественно варианты существующих хвостов: это НЕ доказывает устойчивость к добавлению произвольных новых SEO-услуг.",'',
'## Конкретные случаи: полный вход','',
'Категории: 102 штукатурка, 103 плитка, 104 сантехника, 105 электрика, 106 обои/малярные работы.','']
for idx in [0,1]:
 g=groups[idx];lines +=[f'### Группа {idx+1}','']
 if idx==0:
  lines+=['Общий текст предлагает ремонт без конкретизации пяти целевых услуг. В хвосте «Состав работ: укладка плитки и керамогранита» gold=[103] и C_syntax=[103]. При «комплекс работ под ключ» gold=[] и C_syntax=[]. Это содержательное уточнение услуги, а не бессмысленные теги.','']
 else:
  lines+=['Gold пуст у всех вариантов. При «монтаже встроенной подсветки плинтуса и ступеней» C_syntax выбирает 105 с p=0.577901: это формальный FP, но услуга действительно может относиться к электромонтажу. В official_208, строка 189, хвост прямо содержит выравнивание стен и поклейку обоев; модель остаётся на [], p106=0.427549. Соответствие спорному gold здесь не доказывает правильное понимание услуг.','']
 for v in g['variants']:
  if not v['scored_references']:continue
  refs=', '.join(f"{r['split']}:{r['row']}" for r in v['scored_references'])
  lines +=[f'**{refs}**',f"Gold: `{v['golds']}`; C_syntax: `{v['predictions']}`.",'','```text',v['description'],'```','']
lines+=['## Вывод для архитектуры и следующих данных','',
'C_syntax позволяет независимо отклонить все пять категорий, исключает исходную категорию, использует фрагменты по каждой категории и синтаксические признаки. Это соответствует описанным ментором случаям; однако признаки не гарантируют логически безошибочного понимания роли упоминания. Top-3 может поднять SEO-перечисление или характеристику с похожими словами, а CatBoost может принять их за предложение услуги. Такие механизмы риска здесь не локализованы по SHAP/чанкам, поэтому это гипотезы, а не измеренная причина конкретной ошибки.','',
'На ранее вручную рассмотренных 48 реалистичных или сложных правдоподобных примерах V3 C_syntax ошиблась в 12 объявлениях (25%). Маленькая экспертная выборка; это не оценка частоты ошибок на реальном Авито.','',
'Менять архитектуру и массово добавлять отрицания оснований пока нет. Для отдельной проверки полезны реалистичные пары: предложение услуги против материала/проекта; содержательная характеристика против SKU/SEO; редкие названия реальных услуг; явное предложение услуги в конце длинного объявления. Нужны и положительные, и пустые ответы. Нельзя автоматически удалять все хвосты или назначать [] комплексному ремонту. Новые данные в рамках этого аудита не создавались.','',
'Полные найденные группы и вероятности: natural_variants.json (в Git — сжатый natural_variants.json.gz). Воспроизведение из корня проекта:','',
'```sh','/tmp/innopolis-qwen-emb-venv/bin/python output/public-tag-tail-audit/audit.py','/tmp/innopolis-qwen-emb-venv/bin/python output/public-tag-tail-audit/build_report.py','```','']
(P/'report.md').write_text('\n'.join(lines))
print('Report saved; explicit SEO scored groups:',len(seo))
